const b = $input.first().json.body || {};
const type = (b.type === 'series' || b.type === 'tv') ? 'series' : 'movie';
const id = String(b.imdbId || '').trim();
const title = String(b.title || '').trim();
const hasId = /^tt[0-9]+$/.test(id);
const url = hasId
  ? 'https://v3-cinemeta.strem.io/meta/' + type + '/' + id + '.json'
  : 'https://v3-cinemeta.strem.io/catalog/' + type + '/top/search=' + encodeURIComponent(title) + '.json';
return [{ json: { type, id: hasId ? id : '', title, year: String(b.year || ''), url, valid: hasId || title.length > 0 } }];

const p = $('Prepare').first().json;
const r = $input.first().json || {};
if (!p.valid) return [{ json: { found: false } }];
const accents = new RegExp('[' + String.fromCharCode(0x300) + '-' + String.fromCharCode(0x36f) + ']', 'g');
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(accents, '').replace(/[^a-z0-9]+/g, ' ').trim();
let meta = null;
if (r.meta && r.meta.id) meta = r.meta;
else if (Array.isArray(r.metas)) {
  const ty = norm(p.title);
  const y = parseInt(p.year, 10);
  const yr = m => parseInt(String(m.year || m.releaseInfo || '').slice(0, 4), 10);
  const c = r.metas;
  const near = m => !y || Math.abs(yr(m) - y) <= 1;
  meta = c.find(m => norm(m.name) === ty && near(m))
    || (y ? c.find(m => near(m) && (norm(m.name).indexOf(ty) === 0 || ty.indexOf(norm(m.name)) === 0)) : null);
}
if (!meta || !/^tt[0-9]+$/.test(String(meta.id))) return [{ json: { found: false } }];
const now = new Date().toISOString();
const item = {
  _id: meta.id,
  name: meta.name,
  type: p.type,
  poster: meta.poster || ('https://images.metahub.space/poster/medium/' + meta.id + '/img'),
  posterShape: 'poster',
  removed: false,
  temp: false,
  _ctime: now,
  _mtime: now,
  state: { lastWatched: now, timeWatched: 0, timeOffset: 0, overallTimeWatched: 0, timesWatched: 0, flaggedWatched: 0, duration: 0, video_id: meta.id, watched: '', noNotif: false, season: 0, episode: 0 },
  year: String(meta.year || meta.releaseInfo || '').slice(0, 4)
};
return [{ json: { found: true, id: meta.id, name: meta.name, changes: [item] } }];
